package service
import("context";"path/filepath";"testing";"task133-structload/internal/clock";"task133-structload/internal/store")
func TestBug30_ManualLoadCreationRollsBackWhenAuditWriteFails(t *testing.T){st,e:=store.Open(filepath.Join(t.TempDir(),"l.db"));if e!=nil{t.Fatal(e)};defer st.Close();ctx:=context.Background();svc:=New(st,clock.Real{});p,_:=svc.CreateProject(ctx,CreateProjectInput{Code:"P",Name:"p",Exposure:"C",Importance:"II",WindSpeed:380});l,_:=svc.CreateLevel(ctx,p.ID,CreateLevelInput{Name:"L",GrossArea:100});c,_:=svc.CreateComponent(ctx,"",CreateComponentInput{LevelID:l.ID,Code:"B",Type:"beam",Span:4000,KLL:1,PhiB:90,PhiC:90,PhiV:90,WindSurface:"none"});st.DB().ExecContext(ctx,`CREATE TRIGGER reject_load_event BEFORE INSERT ON event_log WHEN NEW.event_type='add_loadcase' BEGIN SELECT RAISE(ABORT,'blocked'); END`);if _,e=svc.AddManualLoadCase(ctx,c.ID,AddManualLoadCaseInput{Kind:"D",LoadType:"area_pressure",Magnitude:120,Direction:"gravity"});e==nil{t.Fatal("should fail")};lcs,_:=svc.ListLoadCases(ctx,c.ID);if len(lcs)!=0{t.Fatalf("left=%+v",lcs)}}
